-- History pivot / #187: Século XX e as Guerras Mundiais
-- Generated by generators/emit_trail_sql.py from generators/trail_seculo_xx_guerras.py.
-- Idempotent. One transaction. Pair with matching .rollback.sql.
-- DO NOT apply without owner go-ahead. Dry-run with BEGIN + RAISE EXCEPTION.

BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 25, 'Século XX e as Guerras Mundiais', '🌍', '#1E3A8A', 1, 'Da Belle Époque à queda do Muro: guerras totais, crise econômica, fascismos, Holocausto, descolonização e a ordem que nasceu em 1945 e se desfez em 1991.'
WHERE NOT EXISTS (SELECT 1 FROM public.modulos WHERE titulo = 'Século XX e as Guerras Mundiais');

CREATE TEMP TABLE _seed_trail AS
SELECT id AS modulo_id FROM public.modulos WHERE titulo = 'Século XX e as Guerras Mundiais';

INSERT INTO public.niveis (modulo_id, ordem, titulo)
SELECT t.modulo_id, v.ordem, v.titulo
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 'Nível 1 - Grande Guerra'),
  (2, 'Nível 2 - Crise e fascismos'),
  (3, 'Nível 3 - Segunda Guerra'),
  (4, 'Nível 4 - Guerra Fria e fim de século')
) AS v(ordem, titulo)
WHERE NOT EXISTS (
  SELECT 1 FROM public.niveis n WHERE n.modulo_id = t.modulo_id AND n.ordem = v.ordem
);

INSERT INTO public.submodulos (modulo_id, nivel_id, ordem, titulo, data_liberacao_desde_inicio, imagem_url)
SELECT t.modulo_id, n.id, v.ordem, v.titulo, 0, NULL
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 1, 'Belle Époque e rivalidades'),
  (1, 2, '1914–1918: a Grande Guerra'),
  (1, 3, 'Tratados e o mapa novo'),
  (2, 4, 'Crise de 1929'),
  (2, 5, 'Fascismos e nazismo'),
  (2, 6, 'Guerra Civil Espanhola'),
  (3, 7, 'Segunda Guerra Mundial'),
  (3, 8, 'Holocausto'),
  (3, 9, 'ONU e a ordem do pós-guerra'),
  (4, 10, 'Guerra Fria'),
  (4, 11, 'Descolonização'),
  (4, 12, '1989–1991 e o fim do século curto')
) AS v(nivel_ordem, ordem, titulo)
JOIN public.niveis n ON n.modulo_id = t.modulo_id AND n.ordem = v.nivel_ordem
